// From a gateway message to something the worker can act on: the header split off, and an overlay payload decoded
// from its FlatBuffer (schemas/overlay.fbs, generated into ./generated by `mise run continuum-codegen`) into the
// plain objects overlays.ts works with. Pure: no DOM, no decoder, so it's tested in jsdom.

import * as flatbuffers from 'flatbuffers';
import { Overlay as FbOverlay } from './generated/continuum/overlay.js';
import { type FrameHeader, PayloadType, splitMessage } from './header';
import type { Joint, Overlay, OverlayBox } from './overlays';

/** A gateway message, sorted by what it carries. */
export type Incoming =
  | { kind: 'video'; header: FrameHeader; payload: Uint8Array }
  | { kind: 'jpeg'; header: FrameHeader; payload: Uint8Array }
  | { kind: 'arrow'; header: FrameHeader; payload: Uint8Array }
  | { kind: 'overlay'; header: FrameHeader; overlay: Overlay };

/** Sorts one binary message. Throws for a bad header or an overlay that isn't a FlatBuffer. */
export function sort(buffer: ArrayBuffer): Incoming {
  const { header, payload } = splitMessage(buffer);
  switch (header.payloadType) {
    case PayloadType.video:
      return { kind: 'video', header, payload };
    case PayloadType.jpeg:
      return { kind: 'jpeg', header, payload };
    case PayloadType.arrow:
      return { kind: 'arrow', header, payload };
    case PayloadType.overlay:
      return { kind: 'overlay', header, overlay: decodeOverlay(payload, header.captureUs) };
  }
}

/** Decodes an overlay FlatBuffer. The header's capture time wins when the table's is 0 (an older gateway). */
export function decodeOverlay(payload: Uint8Array, headerCaptureUs: number): Overlay {
  const fb = FbOverlay.getRootAsOverlay(new flatbuffers.ByteBuffer(payload));
  const captureUs = Number(fb.captureUs()) || headerCaptureUs;
  const boxes: OverlayBox[] = [];
  for (let i = 0; i < fb.boxesLength(); i++) {
    const b = fb.boxes(i);
    if (b) boxes.push(box(b));
  }
  const skeletons = [];
  for (let i = 0; i < fb.skeletonsLength(); i++) {
    const s = fb.skeletons(i);
    if (!s) continue;
    const joints: Joint[] = [];
    for (let k = 0; k < s.jointsLength(); k++) {
      const j = s.joints(k);
      if (j) joints.push([j.x(), j.y(), j.confidence()]);
    }
    const b = s.box();
    skeletons.push({
      box: b ? box(b) : { xyxy: [0, 0, 0, 0] as [number, number, number, number], score: 0, label: '', hue: null },
      layout: s.layout() ?? '',
      joints,
    });
  }
  const captions = [];
  for (let i = 0; i < fb.captionsLength(); i++) {
    const c = fb.captions(i);
    if (c) captions.push({ text: c.text() ?? '', speaker: c.speaker() ?? '' });
  }
  return { captureUs, boxes, skeletons, captions };
}

function box(b: {
  x1(): number;
  y1(): number;
  x2(): number;
  y2(): number;
  score(): number;
  label(): string | null;
  hue(): number;
  kind(): string | null;
  id(): string | null;
}): OverlayBox {
  const hue = b.hue();
  const kind = b.kind();
  const id = b.id();
  return {
    xyxy: [b.x1(), b.y1(), b.x2(), b.y2()],
    score: b.score(),
    label: b.label() ?? '',
    hue: hue >= 0 ? hue : null,
    ...(kind ? { kind } : {}),
    ...(id ? { id } : {}),
  };
}
